#[allow(clippy::too_many_arguments)]
pub fn density_scaled(h_m: f64, scale: f64) -> f64 {
    let mut rho: f64 = 0.0;
    let mut h: f64 = (h_m / 1000.0);
    let (mut h0, mut rho0, mut hs) = crate::gen::env::atmosphere(h_m);
    if (h < 0.0) {
        rho = (rho0 * scale);
    } else {
        rho = ((scale * rho0) * crate::pm::exp(((-((h - (h0 / 1000.0)))) / (hs / 1000.0))));
    }
    rho
}
